{"content": "import re\nimport subprocess\n\nout = subprocess.check_output([\"netstat\", \"-ano\"], text=True, encoding=\"utf-8\", errors=\"ignore\")\npids = set()\nfor line in out.splitlines():\n    if \"TCP\" in line and \":8000\" in line and \"LISTENING\" in line:\n        m = re.search(r\"(\\d+)\\s*$\", line)\n        if m:\n            pids.add(m.group(1))\nif not pids:\n    print(\"no listener on 8000\")\nelif pids:\n    for pid in pids:\n        r = subprocess.run([\"taskkill\", \"/PID\", pid, \"/F\"], capture_output=True, text=True)\n        print(f\"kill {pid}: {'OK' if r.returncode == 0 else r.stderr.strip()}\")\nprint(\"done\")", "filePath": "E:\\pomelo-ai\\kill_by_port.py"}